// old date, the SET list the new one.
func (q *Queries) UpdateTransaction(ctx context.Context, arg UpdateTransactionParams) error {
	_, err := q.db.ExecContext(ctx, updateTransaction,
		arg.Type,
		arg.Description,
		arg.Date,
		arg.Column4,
		arg.UpdatedAt,
		arg.ID,
	)
	return err
}

const updateTransactionDescription = `-- name: UpdateTransactionDescription :exec
UPDATE transactions SET description=?, updated_at=? WHERE id=?
`

type UpdateTransactionDescriptionParams struct {
	Description sql.NullString
	UpdatedAt   sql.NullString
	ID          int64
}

func (q *Queries) UpdateTransactionDescription(ctx context.Context, arg UpdateTransactionDescriptionParams) error {
	_, err := q.db.ExecContext(ctx, updateTransactionDescription, arg.Description, arg.UpdatedAt, arg.ID)
	return err
}
